/** Probes the local parse boundaries used by the federation engine. */
class GraphAlgebraCompatibilityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FIRST_GRAPH = VF.createIRI("urn:compat:first");
	private static final IRI SECOND_GRAPH = VF.createIRI("urn:compat:second");
	private static final String QUERY = "SELECT ?g WHERE { GRAPH ?g {} }";

	private SailRepository first;
	private SailRepository second;
	private FedXRepository federation;

	@BeforeEach
	void initializeMembers() {
		first = new SailRepository(new MemoryStore());
		second = new SailRepository(new MemoryStore());
		first.init();
		second.init();
		try (var connection = first.getConnection()) {
			connection.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createLiteral(1), FIRST_GRAPH);
		}
		try (var connection = second.getConnection()) {
			connection.add(VF.createIRI("urn:s"), VF.createIRI("urn:p"), VF.createLiteral(2), SECOND_GRAPH);
		}
		federation = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("first", first),
						EndpointFactory.loadEndpoint("second", second)))
				.create();
		federation.init();
	}

	@AfterEach
	void closeMembers() {
		if (federation != null) {
			federation.shutDown();
		}
		if (first != null) {
			first.shutDown();
		}
		if (second != null) {
			second.shutDown();
		}
	}

	@Test
	void syntaxOnlyDefaultsPreserveLocalGraphAlgebra() {
		for (var options : List.of(QueryParseOptions.DEFAULT, QueryParseOptions.STRICT)) {
			try (var connection = federation.getConnection()) {
				connection.setQueryParseOptions(options);
				var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null);
				assertThat(graphCount(query.getParsedQuery().getTupleExpr()))
						.as("locally prepared FedX algebra")
						.isEqualTo(1);
				try (var result = query.evaluate()) {
					assertThat(QueryResults.asList(result)).extracting(row -> row.getValue("g"))
							.containsExactlyInAnyOrder(FIRST_GRAPH, SECOND_GRAPH);
				}
			}
		}
	}

	@Test
	void queryManagerPlanRetainsGraphBoundary() {
		assertThat(federation.getFederationContext().getQueryManager().getQueryPlan(QUERY)).contains("Graph");
	}

	@Test
	void unknownFederationFactoryConservativelyUsesLegacyAlgebra() {
		FedXRepository custom = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("custom-first", first)))
				.withFederationEvaluationStrategyFactory(new FederationEvaluationStrategyFactory() {
				})
				.create();
		custom.init();
		try (var connection = custom.getConnection()) {
			assertThat(graphCount(connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null)
					.getParsedQuery()
					.getTupleExpr())).isZero();
			assertThat(custom.getFederationContext().getQueryManager().getQueryPlan(QUERY)).doesNotContain("Graph");
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH));
			assertThat(graphCount(connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null)
					.getParsedQuery()
					.getTupleExpr())).isEqualTo(1);
		} finally {
			custom.shutDown();
		}
	}

	@Test
	void singleSourceTextDelegationUsesTheMemberMode() {
		FedXRepository single = FedXFactory.newFederation()
				.withMembers(List.of(EndpointFactory.loadEndpoint("single", first)))
				.create();
		single.init();
		try (var connection = single.getConnection()) {
			connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.LEGACY));
			var query = connection.prepareTupleQuery(QueryLanguage.SPARQL, QUERY, null);
			assertThat(graphCount(query.getParsedQuery().getTupleExpr())).isZero();
			try (var result = query.evaluate()) {
				assertThat(QueryResults.asList(result)).extracting(row -> row.getValue("g"))
						.containsExactly(FIRST_GRAPH);
			}
		} finally {
			single.shutDown();
		}
	}

	@ParameterizedTest
	@EnumSource(GraphAlgebraMode.class)
	void updateWhereKeepsTheFederationModeInsteadOfDelegatingTheOriginalText(GraphAlgebraMode mode) {
		RepositoryInformation info = new RepositoryInformation("writable", "http://writable", "http://unknown",
				EndpointType.LocalStore);
		info.setWritable(true);
		var endpoint = new RepositoryEndpointProvider(first).loadEndpoint(info);
		FedXRepository writable = FedXFactory.newFederation().withMembers(List.of(endpoint)).create();
		writable.init();
		try {
			try (var connection = writable.getConnection()) {
				connection.setQueryParseOptions(QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode));
				connection.prepareUpdate(
						"INSERT { <urn:result> <urn:p> <urn:o> } WHERE { GRAPH <urn:missing> {} }")
						.execute();
			}
			try (var connection = first.getConnection()) {
				assertThat(connection.hasStatement(VF.createIRI("urn:result"), VF.createIRI("urn:p"),
						VF.createIRI("urn:o"), false)).isEqualTo(mode == GraphAlgebraMode.LEGACY);
			}
		} finally {
			writable.shutDown();
		}
	}

	private static int graphCount(TupleExpr expression) {
		AtomicInteger graphs = new AtomicInteger();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph graph) {
				graphs.incrementAndGet();
				super.meet(graph);
			}
		});
		return graphs.get();
	}
}
